// Budget brake: at most 10 msgs/run (Gmail limit above) and 4 attachments
// per message. Filenames carry the Gmail message id so re-runs OVERWRITE
// the same file - idempotent, never duplicates into wf15. Message ids are
// globally unique, so files from this inbox can never collide with wf21's.
const out = [];
for (const item of items) {
  const bins = item.binary || {};
  let n = 0;
  for (const key of Object.keys(bins)) {
    if (n >= 4) break;
    const b = bins[key];
    const orig = (b.fileName || 'statement.dat').replace(/[^A-Za-z0-9._-]/g, '_');
    if (!/\.(ofx|qfx|qbo|csv)$/i.test(orig)) continue;
    const msgId = (item.json.id || 'msg').slice(0, 16);
    out.push({ json: { fileName: `gmail-${msgId}-${orig}` }, binary: { data: b } });
    n++;
  }
}
return out;

// THREE-BRAKES (2026-06-12 review fix). The budget brake already lives in
// the Gmail limit (10 msgs) + 4-attachments cap + executionTimeout. This
// node adds the other two required brakes (CLAUDE.md binding rule):
//   CONCURRENCY LOCK - a prior run still in flight (lock fresher than 30
//   min) means SKIP this fire entirely; runs never stack.
//   KILL-SWITCH - a stale lock means the prior run died mid-flight. Three
//   consecutive stale locks auto-PAUSES the workflow (sd.paused = true);
//   it never auto-continues into a runaway. A human clears it by setting
//   paused=false in workflow static data (or re-importing) after looking.
const sd = $getWorkflowStaticData('global');
const now = Date.now();
if (sd.paused) return [];
if (sd.lockAt && (now - sd.lockAt) < 30 * 60 * 1000) return [];
if (sd.lockAt) {
  sd.strikes = (sd.strikes || 0) + 1;
  if (sd.strikes >= 3) { sd.paused = true; sd.lockAt = null; return []; }
}
sd.lockAt = now;
return items;

// Run completed cleanly: release the concurrency lock and reset the
// kill-switch strike counter.
const sd = $getWorkflowStaticData('global');
sd.lockAt = null;
sd.strikes = 0;
return items;
